CREATE OR REPLACE FUNCTION public.tame_room_refusal(p_world uuid, p_uid uuid)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  select c.name || ' already follows you. Need an empty wildermon crate.'
    from creature c
   where c.world_id = p_world and c.keeper = p_uid and c.mode = 'active' and c.hitched_to is null
     and empty_crate(p_world, p_uid) is null
   limit 1
